Validace a normalizace patří před přístup do úložiště. Jediná služba potom chrání pravidla bez ohledu na to, odkud ji aplikace zavolá. Návratová hodnota popisuje výsledek; podobu zprávy rozhodne obrazovka.

Celý soubor `Main.java` včetně připraveného kódu:

```java
import java.util.*;

public class Main {
  public static void main(String[] args) throws Exception {
    Scanner in = new Scanner(System.in);
    EvidenceRepository repo = new EvidenceRepository();
    EvidenceService service = new EvidenceService(repo);
    int n = Integer.parseInt(in.nextLine());
    for (int i = 0; i < n; i++) System.out.println(service.register(in.nextLine(), in.nextLine()));
    for (Evidence e : repo.all()) System.out.println(e.id() + ":" + e.note());
    System.out.println("Pristupy: " + repo.reads + "/" + repo.writes);
  }
}

enum Result {
  ADDED,
  DUPLICATE,
  INVALID
}

record Evidence(String id, String note) {}

class EvidenceRepository {
  private final Map<String, Evidence> entries = new LinkedHashMap<>();
  int reads = 0, writes = 0;

  boolean contains(String id) {
    reads++;
    return entries.containsKey(id);
  }

  void save(Evidence e) {
    writes++;
    entries.put(e.id(), e);
  }

  Collection<Evidence> all() {
    return entries.values();
  }
}

class EvidenceService {
  // UPRAVUJ ODSUD
  private final EvidenceRepository repo;

  EvidenceService(EvidenceRepository repo) {
    this.repo = repo;
  }

  Result register(String rawId, String rawNote) {
    String id = rawId.trim().toUpperCase(Locale.ROOT), note = rawNote.trim();
    if (id.isEmpty() || note.isEmpty()) return Result.INVALID;
    if (repo.contains(id)) return Result.DUPLICATE;
    repo.save(new Evidence(id, note));
    return Result.ADDED;
  }
  // UPRAVUJ POTUD
}
```

Mapa candidate obsahuje navrhované změny. Pokud uložení selže, služba dál používá původní mapu. Metoda snapshot vrací kopii, takže její úprava neovlivní službu. Připravené úložiště při IOException také zachová původní data.

Celý soubor `Main.java` včetně připraveného kódu:

```java
import java.util.*;

public class Main {
  public static void main(String[] args) throws Exception {
    Scanner in = new Scanner(System.in);
    RoomRepository repo = new RoomRepository();
    RoomService service = new RoomService(repo);
    int n = Integer.parseInt(in.nextLine());
    for (int i = 0; i < n; i++) {
      String name = in.nextLine(), room = in.nextLine();
      repo.failNext = Boolean.parseBoolean(in.nextLine());
      System.out.println(service.move(name, room));
      service.snapshot().clear();
      System.out.println("App: " + service.snapshot());
      System.out.println("Disk: " + repo.snapshot());
    }
    System.out.println("Zapisy: " + repo.calls);
  }
}

class RoomRepository {
  private Map<String, String> saved = new LinkedHashMap<>();
  boolean failNext = false;
  int calls = 0;

  void save(Map<String, String> candidate) throws java.io.IOException {
    calls++;
    if (failNext) {
      failNext = false;
      throw new java.io.IOException("offline");
    }
    saved = new LinkedHashMap<>(candidate);
  }

  Map<String, String> snapshot() {
    return new LinkedHashMap<>(saved);
  }
}

class RoomService {
  // UPRAVUJ ODSUD
  private final RoomRepository repo;
  private Map<String, String> rooms = new LinkedHashMap<>();

  RoomService(RoomRepository repo) {
    this.repo = repo;
  }

  String move(String rawName, String rawRoom) {
    String name = rawName.trim(), room = rawRoom.trim();
    if (name.isEmpty() || (!room.equals("NORTH") && !room.equals("SOUTH"))) return "INVALID";
    Map<String, String> candidate = new LinkedHashMap<>(rooms);
    candidate.put(name, room);
    try {
      repo.save(candidate);
      rooms = candidate;
      return "SAVED";
    } catch (java.io.IOException e) {
      return "RETRY";
    }
  }

  Map<String, String> snapshot() {
    return new LinkedHashMap<>(rooms);
  }
  // UPRAVUJ POTUD
}
```

